"""Payload builder factory for Excel signature verification."""

from __future__ import annotations

from dataclasses import dataclass
import hashlib


@dataclass(slots=True)
class PayloadCandidate:
	"""One payload candidate generated by a canonicalization strategy."""

	name: str
	payload: bytes


@dataclass(slots=True)
class WorkbookPayloadBuilder:
	"""Creates deterministic payload bytes from workbook data for signature verification."""

	signature_version: str = "1.0"

	@staticmethod
	def _normalize_cell(value, trim: bool) -> str:
		if value is None:
			return ""
		text = str(value)
		text = text.replace("\r\n", "\n").replace("\r", "\n")
		return text.strip() if trim else text

	def _sheet_lines(
		self,
		ws,
		*,
		trim: bool,
		include_empty_rows: bool,
		include_coords: bool,
		trim_trailing_empty: bool,
	) -> list[str]:
		lines: list[str] = []
		for row_idx, row in enumerate(ws.iter_rows(values_only=True), start=1):
			cells = [self._normalize_cell(cell, trim=trim) for cell in row]
			if trim_trailing_empty:
				while cells and cells[-1] == "":
					cells.pop()
			has_any = any(cell != "" for cell in cells)
			if not has_any and not include_empty_rows:
				continue
			if include_coords:
				segments = [f"R{row_idx}C{col_idx}={cell}" for col_idx, cell in enumerate(cells, start=1)]
				line = "|".join(segments)
			else:
				line = "|".join(cells)
			lines.append(line)
		return lines

	def build_payload_candidates(self, workbook, source_tag: str = "data_only_false") -> list[PayloadCandidate]:
		"""Generate multiple deterministic payload candidates for production signature parity."""
		strategies = [
			("sheet_rows_raw", False, True, False, False),
			("sheet_rows_trimmed", True, True, False, False),
			("used_rows_raw", False, False, False, True),
			("used_rows_trimmed", True, False, False, True),
			("coords_trimmed", True, False, True, True),
		]

		candidates: list[PayloadCandidate] = []
		for strategy_name, trim, include_empty_rows, include_coords, trim_trailing_empty in strategies:
			parts: list[str] = []
			for ws in workbook.worksheets:
				if ws.title.lower() == "digital signature":
					continue
				parts.append(f"[{ws.title}]")
				parts.extend(
					self._sheet_lines(
						ws,
						trim=trim,
						include_empty_rows=include_empty_rows,
						include_coords=include_coords,
						trim_trailing_empty=trim_trailing_empty,
					)
				)
			parts.append(f"[signature_version={self.signature_version}]")
			payload_text = "\n".join(parts)
			candidates.append(
				PayloadCandidate(
					name=f"{source_tag}:{strategy_name}",
					payload=payload_text.encode("utf-8"),
				)
			)
		return candidates

	def build_payload(self, workbook) -> bytes:
		"""Return the primary candidate payload bytes used for verification."""
		candidates = self.build_payload_candidates(workbook)
		if not candidates:
			return b""
		return candidates[0].payload

	def build_payload_sha256(self, workbook) -> str:
		"""Return hex SHA-256 of the generated payload for parity checks."""
		return hashlib.sha256(self.build_payload(workbook)).hexdigest()

	def collect_structure_diagnostics(self, workbook) -> dict[str, int]:
		"""Collect workbook structure characteristics relevant to signing parity."""
		merged_ranges = 0
		hidden_rows = 0
		hidden_cols = 0
		empty_rows = 0
		for ws in workbook.worksheets:
			if ws.title.lower() == "digital signature":
				continue
			merged_ranges += len(getattr(ws, "merged_cells", []).ranges) if hasattr(getattr(ws, "merged_cells", None), "ranges") else 0
			hidden_rows += sum(1 for _, dim in ws.row_dimensions.items() if getattr(dim, "hidden", False))
			hidden_cols += sum(1 for _, dim in ws.column_dimensions.items() if getattr(dim, "hidden", False))
			for row in ws.iter_rows(values_only=True):
				if not any(cell not in (None, "") for cell in row):
					empty_rows += 1
		return {
			"merged_ranges": merged_ranges,
			"hidden_rows": hidden_rows,
			"hidden_columns": hidden_cols,
			"empty_rows": empty_rows,
		}


class PayloadBuilderFactory:
	"""Factory returning payload builder compatible with workbook signature version."""

	@staticmethod
	def get_builder(workbook, signature_version: str = "1.0") -> WorkbookPayloadBuilder:
		"""Return a deterministic payload builder for the provided workbook."""
		_ = workbook
		return WorkbookPayloadBuilder(signature_version=signature_version)

